INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(105808, 'ruRU', '', 'Я нарежу тебя на корм для угрей!', 24330),
(105809, 'ruRU', '', 'Ты вторгся в воды Сашь''тар!', 24330),
(105810, 'ruRU', '', 'Смерть идёт за тобой!', 24330),
(105811, 'ruRU', '', 'Убить незваного гостя!', 24330),
(105812, 'ruRU', '', 'Моя жизнь за Сашь''тар...', 24330),
(105813, 'ruRU', '', 'Я проклинаю тебя!', 24330),
(105814, 'ruRU', '', 'Моя смерть не важна...', 24330),
(105815, 'ruRU', '', 'Тебе не остановить Госпожу Приливов...', 24330),
(105816, 'ruRU', '', 'Нас... не... остановить...', 24330),
(105817, 'ruRU', '', 'Тьма в глубинах...', 24330),
(105818, 'ruRU', '', 'Ты, слизь...', 24330),
(105819, 'ruRU', '', 'Госпожа Приливов...', 24330),
(105867, 'ruRU', '', 'Те чегой-то надо?', 24330),
(105871, 'ruRU', '', 'Вот наш шанс!', 24330),
(105873, 'ruRU', '', 'Ну шо, пора глянуть, выйдет ли у нас это взаправду сделать. Тут понадобится всё, шо у нас есть, и ещё поверх того.', 24330),
(105874, 'ruRU', '', 'Зен''табра на мгновение закрывает глаза.', 24330),
(105881, 'ruRU', '', 'Духи, они молчат мне про это. Значит, они тож не против. Ну ладно, встренемся на ритуале.', 24330),
(105888, 'ruRU', '', 'Благодарю, незнакомец.', 24330),
(105899, 'ruRU', '', '...и приведи с собой чужеземца.', 24330),
(105900, 'ruRU', '', 'Если... ты настаиваешь.', 24330),
(105901, 'ruRU', '', 'А Валтруа?', 24330),
(105902, 'ruRU', '', 'Было бы мудро не задирать нос перед чужеземцами. Никого из нас здесь не было бы без их помощи.', 24330),
(105903, 'ruRU', '', 'Разумеется, Первый чародей.', 24330),
(105904, 'ruRU', '', 'Идём, мы можем изучить поток отсюда снизу.', 24330),
(105905, 'ruRU', '', 'Приветствую, $c!$B$BЯ выследил группу Сашь''тар через залив до этой пещеры.$B$BМногие пали от моего клинка, но некоторые сумели ускользнуть. Не сомневаюсь, что они вернутся в бóльшем числе, чтобы попытаться убить меня.$B$BЕсли ты не против славной битвы, укрепи свой дух и приготовь оружие.$B$BЕсли нет — не путайся у меня под ногами, иначе я убью тебя сам.', 24330),
(105906, 'ruRU', '', 'У тебя большой опыт обращения с энергией лей-линий? Полагаю, что нет.', 24330),
(105907, 'ruRU', '', 'Позволь мне просветить тебя об основах.', 24330),
(105908, 'ruRU', '', 'Ты отличный $c. Я с радостью снова буду сражаться рядом с тобой!$B$BКогда я вернусь в Яндвик, мы споём песни о нашей битве за кружками эля!', 24330),
(105909, 'ruRU', '', 'Далеко под нами по всей земле текут реки первозданной тайной силы. Лей-линии вечны, изначальны и неподвластны контролю.', 24330),
(105911, 'ruRU', '', 'Однако, подобно тому как из хлопка вытягивают нить, так и мы можем черпать силу из лей-линий.', 24330),
(105915, 'ruRU', '', 'На кого бы ты ни охотился, у Разика найдётся приспособление, гарантированно способное свалить твою цель.\n\nЕго последние прототипы уже заряжены и готовы к использованию. Просто возьми один со стойки с оружием и начинай стрелять.\n\nТолько помни — испытываешь на свой страх и риск!', 24330),
(105925, 'ruRU', '', 'Вот они идут!', 24330),
(105926, 'ruRU', '', 'Мы победили!', 24330),
(105930, 'ruRU', '', 'Смотри сюда. Это поток от Аноры. И есть ещё многие другие, что всё ещё бездействуют.', 24330),
(105931, 'ruRU', '', 'Восстанови их и помоги нам создать новый очаг силы здесь, в Шал''Аране!', 24330),
(105940, 'ruRU', '', 'Базар Василисков — весьма опасное мероприятие, которое устраивают дрогбары: там они торгуют, дерутся и свежуют своих ящериц-питомцев. Срыв этого мероприятия отбросит их силы на шаг-другой назад и обезопасит наши местные фермерские земли на время.', 24330),
(105941, 'ruRU', '', 'Раньше я восхищался родством дрогбаров с природой, пока они не использовали его, чтобы истреблять мой народ и нападать на мои земли. Прими мою благодарность, защитник.', 24330),
(105942, 'ruRU', '', 'Осколковладыки из Серого Камня проводят какой-то усиливающий ритуал в расщелине Хрустального Разлома. Это слишком близко к Громовому Тотему, чтобы чувствовать себя спокойно. Можешь остановить их?', 24330),
(105943, 'ruRU', '', 'Спасибо, защитник. Дрогбары из Серого Камня в последнее время становятся слишком амбициозными.', 24330),
(105946, 'ruRU', '', 'Я слышу крик земли. Осколковладыки дрогбаров проводят тёмный ритуал, что приводит этих кристальных фурий в ужасающую ярость. Фурий нужно остановить, прежде чем они причинят неисчислимый урон Громовому Тотему.', 24330);
